import { useEffect, useState } from 'react';
import { createTask, deleteTask, getTasks, updateTask } from './api';
import './dashboard.css';

function Dashboard({ userName, userRole, onLogout }) {
    const [activePage, setActivePage] = useState('Dashboard');
    const [search, setSearch] = useState('');
    const [newTask, setNewTask] = useState('');
    const [tasks, setTasks] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState('');

    useEffect(() => {
        async function loadTasks() {
            try {
                const response = await getTasks();
                setTasks(response.data.map((task) => ({ ...task, id: task._id, done: task.completed })));
            } catch (loadError) {
                setError(loadError.message);
            } finally {
                setIsLoading(false);
            }
        }
        loadTasks();
    }, []);

    const completedTasks = tasks.filter((task) => task.done).length;
    const progress = tasks.length ? Math.round((completedTasks / tasks.length) * 100) : 0;

    function toggleTask(id) {
        const task = tasks.find((item) => item.id === id);
        if (!task) return;
        const completed = !task.done;
        updateTask(id, { completed })
            .then((response) => setTasks(tasks.map((item) => item.id === id ? { ...item, done: response.data.completed } : item)))
            .catch((updateError) => setError(updateError.message));
    }

    function addTask(event) {
        event.preventDefault();
        if (!newTask.trim()) return;
        createTask(newTask)
            .then((response) => {
                const task = response.data;
                setTasks([{ ...task, id: task._id, done: task.completed }, ...tasks]);
                setNewTask('');
            })
            .catch((createError) => setError(createError.message));
    }

    function removeTask(id) {
        deleteTask(id)
            .then(() => setTasks(tasks.filter((task) => task.id !== id)))
            .catch((deleteError) => setError(deleteError.message));
    }

    const pages = [
        ['Dashboard'],
        ['Tasks'],
        ['Projects'],
        ['Analytics'],
        ['Calendar'],
    ];

    return (
        <main className="dashboard-page">
            <div className="dashboard-shell">
                <aside className="dashboard-sidebar">
                    <div className="product-logo"><span className="logo-icon">◆</span> Task Manager</div>
                    <p className="menu-label">Menu</p>
                    <nav aria-label="Main navigation">
                        {pages.map(([page, icon]) => (
                            <button className={`nav-item ${activePage === page ? 'active' : ''}`} type="button" key={page} onClick={() => setActivePage(page)}>
                                <span>{icon}</span>{page}
                            </button>
                        ))}
                        {userRole !== 'User' && <button className={`nav-item ${activePage === 'Team Members' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Team Members')}><span></span>Team Members</button>}
                        {userRole === 'Admin' && <button className={`nav-item ${activePage === 'Manage Users' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Manage Users')}><span></span>Manage Users</button>}
                    </nav>
                    <p className="menu-label general-label">General</p>
                    <button className="nav-item" type="button" onClick={() => setActivePage('Settings')}><span></span>Settings</button>
                    <button className="nav-item" type="button" onClick={onLogout}><span></span>Logout</button>
                    <div className="upgrade-box"><strong>Task Manager</strong><p>Keep your work organized and on schedule.</p></div>
                </aside>

                <section className="dashboard-main">
                    <header className="dashboard-topbar">
                        <div>
                            <p className="dashboard-label">{activePage}</p>
                            <h1>Welcome back, {userName}!</h1>
                            <p>Here&apos;s what is happening with your tasks today.</p>
                        </div>
                        <div className="topbar-actions">
                            <label className="search-box"><span>⌕</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search tasks..." aria-label="Search tasks" /></label>
                            <div className="account-box"><span className="user-avatar">{userName.charAt(0).toUpperCase()}</span><span><strong>{userName}</strong><small>{userRole} account</small></span></div>
                        </div>
                    </header>

                    {activePage === 'Dashboard' && (
                        <>
                            <section className="metric-grid" aria-label="Task summary">
                                <article className="metric-card blue"><strong>{tasks.length}</strong><span>Total Tasks</span></article>
                                <article className="metric-card green"><strong>{completedTasks}</strong><span>Completed</span></article>
                                <article className="metric-card purple"><strong>{tasks.length - completedTasks}</strong><span>Remaining</span></article>
                                <article className="metric-card pink"><strong>{progress}%</strong><span>Progress</span></article>
                            </section>
                            <section className="dashboard-cards">
                                <article className="panel task-panel">
                                    <div className="panel-heading"><div><h2>My Tasks</h2><p>Complete your tasks for today.</p></div><span>{completedTasks}/{tasks.length}</span></div>
                                    <form className="quick-task-form" onSubmit={addTask}><input value={newTask} onChange={(event) => setNewTask(event.target.value)} placeholder="Add a new task" aria-label="New task" /><button type="submit">Add</button></form>
                                    {error && <p className="task-error" role="alert">{error}</p>}
                                    {isLoading ? <p className="task-empty">Loading tasks...</p> : <div className="task-list">{tasks.filter((task) => task.title.toLowerCase().includes(search.toLowerCase())).map((task) => <div className={`quick-task ${task.done ? 'done' : ''}`} key={task.id}><input type="checkbox" checked={task.done} onChange={() => toggleTask(task.id)} /><span>{task.title}</span><button className="delete-task" type="button" onClick={() => removeTask(task.id)} aria-label={`Delete ${task.title}`}>x</button></div>)}</div>}
                                </article>
                                <article className="panel progress-panel"><div className="panel-heading"><div><h2>Today&apos;s Progress</h2><p>Keep moving forward.</p></div></div><div className="progress-circle" style={{ '--progress': `${progress}%` }}><strong>{progress}%</strong></div><p>{progress === 100 ? 'All tasks completed!' : `${tasks.length - completedTasks} tasks left to finish.`}</p></article>
                            </section>
                        </>
                    )}

                    {activePage !== 'Dashboard' && (
                        <section className="working-page panel">
                            <p className="dashboard-label">Workspace</p>
                            <h2>{activePage}</h2>
                            <p>This section is ready for your {activePage.toLowerCase()}.</p>
                            {activePage === 'Tasks' && <><form className="quick-task-form" onSubmit={addTask}><input value={newTask} onChange={(event) => setNewTask(event.target.value)} placeholder="Write a new task" aria-label="New task" /><button type="submit">Add Task</button></form>{error && <p className="task-error" role="alert">{error}</p>}</>}
                        </section>
                    )}
                </section>
            </div>
        </main>
    );
}

export default Dashboard;
